import fs from 'node:fs';
import { abs, readKitConfig } from './project.mjs';

const HEADER = `// ────────────────────────────────────────────────────────────────
//  AUTO-GENERATED by the kit CLI (\`npm run kit add|remove <module>\`).
//  Do not edit by hand — changes will be overwritten.
// ────────────────────────────────────────────────────────────────`;

const camel = (name) => name.replace(/[-_]+(\w)/g, (_, c) => c.toUpperCase());

const hasEntry = (dir) => ['index.ts', 'index.tsx'].some((f) => fs.existsSync(abs(`${dir}/${f}`)));

function render({ typeImport, typeName, names }) {
  const imports = names.map((n) => `import ${camel(n)} from './${n}';`);
  const list = names.length ? `[\n${names.map((n) => `  ${camel(n)},`).join('\n')}\n]` : '[]';
  return `${HEADER}\n${typeImport}\n${imports.join('\n')}${imports.length ? '\n' : ''}\nexport const installedModules: ${typeName}[] = ${list};\n`;
}

/**
 * Rewrites the API and web module registries from kit.json. A module is
 * registered in an app when it ships `src/modules/<name>/index.ts(x)` there.
 */
export function generateRegistries() {
  const installed = Object.keys(readKitConfig().modules);

  const apiNames = installed.filter((n) => hasEntry(`apps/api/src/modules/${n}`));
  fs.writeFileSync(
    abs('apps/api/src/modules/registry.ts'),
    render({ typeImport: "import type { ApiModule } from '../core/module';", typeName: 'ApiModule', names: apiNames }),
  );

  const webNames = installed.filter((n) => hasEntry(`apps/web/src/modules/${n}`));
  fs.writeFileSync(
    abs('apps/web/src/modules/installed.ts'),
    render({ typeImport: "import type { WebModule } from './types';", typeName: 'WebModule', names: webNames }),
  );

  return { api: apiNames, web: webNames };
}
